 * Each entry is stamped with a monotonically increasing insertion sequence
 * number so that entries with equal priority leave in the order they were
 * pushed, regardless of any priority changes made afterwards.
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #index = new Map();

  /** @type {number} */
  #seq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Validates a key.
   * @param {unknown} key Candidate key.
   * @returns {void}
   */
  #checkKey(key) {
    if (typeof key !== 'string') throw new TypeError('key must be a string');
  }

