   * Sifts the entry at a position up towards the root as needed.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftUp(pos) {
    const items = this.#items;
    while (pos > 0) {
      const parent = (pos - 1) >> 1;
      if (this.#compare(items[pos], items[parent]) < 0) {
        this.#swap(pos, parent);
        pos = parent;
      } else break;
    }
  }

  /**
   * Sifts the entry at a position down towards the leaves as needed.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftDown(pos) {
    const items = this.#items;
    const n = items.length;
    while (true) {
      const left = 2 * pos + 1;
      const right = 2 * pos + 2;
      let smallest = pos;
      if (left < n && this.#compare(items[left], items[smallest]) < 0) smallest = left;
      if (right < n && this.#compare(items[right], items[smallest]) < 0) smallest = right;
      if (smallest === pos) break;
