import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  const peek = () => tokens[pos];
  const advance = () => tokens[pos++];

  const tokenText = (tok) => (typeof tok.value === 'number' ? String(tok.value) : String(tok.value));

  const unexpected = (tok) => {
    if (tok === undefined) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }
    throw new ExprError(`unexpected token '${tokenText(tok)}' at ${tok.index}`, tok.index);
  };

  function parsePrimary() {
    const tok = peek();
    if (tok === undefined) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }

    if (tok.type === 'number') {
      advance();
      return { type: 'number', value: tok.value, index: tok.index };
    }

    if (tok.type === 'name') {
      advance();
      const next = peek();
      if (next !== undefined && next.type === 'lparen') {
        advance();
        const args = [];
        const afterLparen = peek();
        if (afterLparen !== undefined && afterLparen.type === 'rparen') {
          advance();
        } else {
          for (;;) {
            args.push(parseExpression());
            const sep = peek();
            if (sep !== undefined && sep.type === 'comma') {
              advance();
              continue;
            }
            if (sep !== undefined && sep.type === 'rparen') {
              advance();
              break;
            }
            unexpected(sep);
          }
        }
        return { type: 'call', name: tok.value, args, index: tok.index };
      }
      return { type: 'variable', name: tok.value, index: tok.index };
    }

    if (tok.type === 'lparen') {
      advance();
      const expr = parseExpression();
      const next = peek();
      if (next !== undefined && next.type === 'rparen') {
        advance();
        return expr;
      }
      const idx = next !== undefined ? next.index : input.length;
      throw new ExprError(`missing closing parenthesis at ${idx}`, idx);
    }

    unexpected(tok);
  }

  function parsePow() {
    const left = parsePrimary();
    const tok = peek();
    if (tok !== undefined && tok.type === 'operator' && tok.value === '^') {
      advance();
      const right = parseUnary();
      return { type: 'binary', op: '^', left, right, index: tok.index };
    }
    return left;
  }

  function parseUnary() {
    const tok = peek();
    if (tok !== undefined && tok.type === 'operator' && (tok.value === '+' || tok.value === '-')) {
      advance();
      const operand = parseUnary();
      return { type: 'unary', op: tok.value, operand, index: tok.index };
    }
    return parsePow();
  }

  function parseMulDiv() {
    let left = parseUnary();
    for (;;) {
      const tok = peek();
      if (tok !== undefined && tok.type === 'operator' && (tok.value === '*' || tok.value === '/' || tok.value === '%')) {
        advance();
        const right = parseUnary();
        left = { type: 'binary', op: tok.value, left, right, index: tok.index };
        continue;
      }
      return left;
    }
  }

