    let left = parseMulDiv();
    for (;;) {
      const tok = peek();
      if (tok !== undefined && tok.type === 'operator' && (tok.value === '+' || tok.value === '-')) {
        advance();
        const right = parseMulDiv();
        left = { type: 'binary', op: tok.value, left, right, index: tok.index };
