 * Prefix index over Unicode strings.
 *
 * A real trie: one node per distinct prefix, walked by Unicode code point so
 * a character outside the basic plane is a single step and never a pair of
 * surrogate halves. Each node keeps a count of the stored words below it so
 * `countPrefix` costs only the length of the prefix.
 */

/**
 * @typedef {object} TrieNode
 * @property {Map<string, TrieNode>} children Child nodes keyed by code point.
 * @property {boolean} isEnd Whether a word ends at this node.
 * @property {unknown} value Value stored when isEnd is true.
 * @property {number} count Number of stored words at or below this node.
 */

/**
 * Creates a fresh, empty trie node.
 * @returns {TrieNode} New node.
 */
function makeNode() {
  return { children: new Map(), isEnd: false, value: undefined, count: 0 };
}

/**
 * Validates that a value is a string, raising a labelled TypeError otherwise.
 * @param {unknown} value Value to check.
 * @param {string} label Name to use in the error message.
 * @returns {void}
 */
function checkString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string`);
  }
}

/**
 * Validates a search limit: Infinity or a non-negative safe integer.
 * @param {unknown} limit Value to check.
 * @returns {void}
 */
function checkLimit(limit) {
  const ok = limit === Number.POSITIVE_INFINITY || (Number.isSafeInteger(limit) && limit >= 0);
  if (!ok) {
    throw new TypeError('limit must be a non-negative integer');
  }
}

export class Trie {
  /** @type {TrieNode} */
  #root = makeNode();

  /** @type {number} */
  #size = 0;

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    checkString(word, 'word');
    const chars = [...word];
    let node = this.#root;
    for (const ch of chars) {
      let next = node.children.get(ch);
      if (next === undefined) {
        next = makeNode();
        node.children.set(ch, next);
        this.#nodeCount += 1;
      }
      node = next;
    }
    const wasEnd = node.isEnd;
    const previous = node.value;
    if (!wasEnd) {
      // Increment the count for every node on the path, root included.
      let n = this.#root;
      n.count += 1;
      for (const ch of chars) {
        n = n.children.get(ch);
        n.count += 1;
      }
      this.#size += 1;
