   * Finds the node for a word, if any.
   * @param {string} word Word to look up.
   * @returns {TrieNode | undefined} The node, or undefined when absent.
   */
  #findNode(word) {
    let node = this.#root;
    for (const ch of word) {
      const next = node.children.get(ch);
      if (next === undefined) return undefined;
      node = next;
    }
    return node;
  }

