    let node = this.#root;
    for (const ch of chars) {
      const next = node.children.get(ch);
      if (next === undefined) return false;
      path.push({ node, ch });
      node = next;
    }
    if (!node.isEnd) return false;

    node.isEnd = false;
    node.value = undefined;
