   * Depth-first collects stored words below a node, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word prefix accumulated so far.
   * @param {string[]} out Accumulator for matching words.
   * @param {number} limit Maximum number of words to collect.
   * @returns {void}
   */
  #collect(node, prefix, out, limit) {
    if (out.length >= limit) return;
    if (node.isEnd) {
      out.push(prefix);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
