      this.#collect(node.children.get(ch), prefix + ch, out, limit);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collectEntries(this.#root, '', out);
    return out;
  }

  /**
   * Depth-first collects stored [word, value] pairs, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word prefix accumulated so far.
   * @param {Array<[string, unknown]>} out Accumulator for matching pairs.
   * @returns {void}
   */
  #collectEntries(node, prefix, out) {
    if (node.isEnd) out.push([prefix, node.value]);
    const keys = [...node.children.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
    for (const ch of keys) {
      this.#collectEntries(node.children.get(ch), prefix + ch, out);
    }
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    checkString(text, 'text');
    let node = this.#root;
    let best = null;
    if (node.isEnd) best = { word: '', value: node.value };
    let consumed = '';
    for (const ch of text) {
      const next = node.children.get(ch);
      if (next === undefined) break;
      node = next;
      consumed += ch;
      if (node.isEnd) best = { word: consumed, value: node.value };
    }
    return best;
  }
}
