   * Depth-first collects stored [word, value] pairs, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word prefix accumulated so far.
   * @param {Array<[string, unknown]>} out Accumulator for matching pairs.
   * @returns {void}
   */
  #collectEntries(node, prefix, out) {
    if (node.isEnd) out.push([prefix, node.value]);
    const keys = [...node.children.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
