    /** @type {Map<number, number[]>} */
    const byRoot = new Map();
    for (let element = 0; element < this.#parent.length; element += 1) {
      const root = this.find(element);
      const members = byRoot.get(root);
      if (members === undefined) byRoot.set(root, [element]);
