    try {
      expected = compute(tree);
    } catch {
      continue;
    }
    const source = render(tree);
    assert.equal(evaluate(source), expected, `${source} should be ${expected}`);
    assert.equal(evaluate(renderFully(tree)), expected, `${renderFully(tree)} should be ${expected}`);
    checked += 1;
  }
