    this.#getAccountOrThrow(accountId);
    const { asOf = Infinity } = options;
    if (asOf !== Infinity) this.#checkAsOf(asOf);
    let total = 0;
    for (const entry of this.#entries.values()) {
      if (entry.at > asOf) continue;
      for (const line of entry.lines) {
        if (line.account === accountId) total += line.amountCents;
      }
    }
    return total;
  }

