    }
    const lines = original.lines.map((line) => ({ account: line.account, amountCents: -line.amountCents }));
    const reversal = this.post({ id, at, memo, lines });
    const linkedReversal = Object.freeze({ ...reversal, reverses: entryId });
    this.#setEntry(id, linkedReversal);
    const updatedOriginal = Object.freeze({ ...original, reversedBy: id });
    this.#setEntry(entryId, updatedOriginal);
    return linkedReversal;
  }

  /**
   * Every line touching one account inside a window, with a running balance.
   *
   * @param {string} accountId Account to report on.
   * @param {{from?: number, to?: number}} [options] Inclusive window.
   * @returns {Array<{entryId: string, at: number, seq: number, amountCents: number, balanceCents: number}>} Statement rows.
   */
  statement(accountId, options = {}) {
    this.#getAccountOrThrow(accountId);
    const { from = -Infinity, to = Infinity } = options;
    const rows = [];
    let running = 0;
    for (const entry of this.#orderedEntries()) {
      for (const line of entry.lines) {
