/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATORS = new Set(['+', '#', '.', '/', ';', '?', '&']);
const RESERVED_OPERATORS = new Set(['=', ',', '!', '@', '|']);

const NAME_RE = /^(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+(?:\.(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+)*$/;
const PREFIX_RE = /^[1-9][0-9]{0,3}$/;

function parseVarSpec(spec, start) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);

  let explode = false;
  let name;
  let modText = null;

  if (spec.endsWith('*')) {
    explode = true;
    name = spec.slice(0, -1);
  } else {
    const idx = spec.indexOf(':');
    if (idx !== -1) {
      name = spec.slice(0, idx);
      modText = spec.slice(idx + 1);
    } else {
      name = spec;
    }
  }

  if (!NAME_RE.test(name)) {
    throw new UriTemplateError(`invalid variable name '${name}' at ${start}`, start);
  }

  let maxLength = null;
  if (modText !== null) {
    if (!PREFIX_RE.test(modText)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modText}' at ${start}`, start);
    }
    maxLength = Number.parseInt(modText, 10);
  }

  return { name, explode, maxLength };
}

function parseExpression(body, start) {
  let operator = '';
  let rest = body;
  const first = body[0];

  if (OPERATORS.has(first)) {
    operator = first;
    rest = body.slice(1);
  } else if (RESERVED_OPERATORS.has(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${start}`, start);
  }

  const specs = rest.split(',');
  const variables = specs.map((spec) => parseVarSpec(spec, start));

  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');

  const parts = [];
  let literal = '';
  let i = 0;

  const flushLiteral = () => {
    if (literal !== '') {
      parts.push({ type: 'literal', value: literal });
      literal = '';
    }
  };

  while (i < template.length) {
    const ch = template[i];
    if (ch === '{') {
      const start = i;
      const end = template.indexOf('}', i + 1);
      if (end === -1) throw new UriTemplateError(`unterminated expression at ${start}`, start);
      const body = template.slice(i + 1, end);
      if (body === '') throw new UriTemplateError(`empty expression at ${start}`, start);
      flushLiteral();
      parts.push(parseExpression(body, start));
      i = end + 1;
    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literal += ch;
      i += 1;
    }
  }

  flushLiteral();
  return parts;
}
