    for (const entry of all) {
      for (const line of entry.lines) {
        if (line.account !== accountId) continue;
        running += line.amountCents;
        if (entry.at >= from && entry.at <= to) {
          rows.push({
            entryId: entry.id,
            at: entry.at,
            seq: entry.seq,
            amountCents: line.amountCents,
            balanceCents: running,
          });
        }
      }
    }
    return rows;
  }
}"}

